values ('dialog_blacksmith_greet', NULL, 'npc_master_blacksmith', 'greet', '[{"id": "greet", "text": "The forge never sleeps, and neither do I. What do you need — fresh gear, materials, or do you want to push your existing equipment to its limits?", "options": [{"text": "Upgrade my equipment.", "next": "upgrade", "action": "open_upgrade"}, {"text": "Craft new equipment.", "next": "craft", "action": "open_crafting"}, {"text": "Buy materials.", "next": "shop", "action": "open_shop"}, {"text": "Leave.", "next": "exit", "action": "exit"}]}, {"id": "craft", "text": "Let''s see what we can forge.", "options": []}, {"id": "shop", "text": "These materials should serve you well.", "options": []}, {"id": "upgrade", "text": "Enhancement Workshop — bring your gear to its true potential. Safe up to +3, but higher levels carry real risk. Prima Materia for +8 and beyond.", "options": []}]'::jsonb, 'dialog_tree_master.json', 1)
