values ('dialog_valen_main', NULL, 'npc_concordium_officer', 'greet', '[{"id": "greet", "text": "Citizen, security around Nexus has tightened. We could use capable fighters.", "options": [{"text": "I''m ready to help.", "next": "quest", "action": "accept_quest"}, {"text": "Any updates?", "next": "info"}, {"text": "Not now.", "next": "exit", "action": "exit"}]}, {"id": "info", "text": "Strange creatures have been appearing near the Cradle perimeter.", "options": [{"text": "I''ll handle it.", "next": "quest", "action": "accept_quest"}, {"text": "I''ll return later.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_tree_master.json', 4)
