values ('dialog_exchange_concordium', NULL, 'npc_concordium_exchange_officer', 'greet', '[{"id": "greet", "text": "Welcome to the Concordium Treasury. Exchange services available.", "options": [{"text": "Exchange Concordium Credits.", "next": "exchange", "action": "currency_exchange"}, {"text": "Explain the exchange rates.", "next": "rates"}, {"text": "Leave.", "next": "exit", "action": "exit"}]}, {"id": "rates", "text": "Faction currencies convert into CRD — the universal trade credit recognized across Xylos.", "options": [{"text": "Proceed with exchange.", "next": "exchange", "action": "currency_exchange"}, {"text": "Back.", "next": "greet"}]}]'::jsonb, 'dialog_tree_master.json', 5)
