insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_concordium', NULL, 'npc_concordium_class_trainer', 'greet', '[{"id": "greet", "text": "Discipline and unity define the Concordium. What training do you seek?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "I want a mission to prove my worth.", "next": "take_quest"}, {"text": "Tell me about Concordium combat doctrine.", "next": "lore"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Concordium fighters are trained to endure and protect. A disciplined soldier can hold the line against any storm.", "options": [{"text": "Understood.", "next": "greet"}, {"text": "That is all.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Choose your combat specialization carefully, soldier. The Concordium demands commitment — once you walk a path, there is no turning back.", "options": [{"text": "Show me the available specializations.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Focus and refine your abilities.", "options": []}, {"id": "take_quest", "text": "The Concordium does not hand out ranks freely. If you seek to advance your specialization, you must first complete a field assignment. Patrol the designated sector, eliminate hostile targets, and return with proof of your discipline. Only then will we consider your promotion.", "options": [{"text": "I''ll prepare first.", "next": "greet"}, {"text": "I''m ready. Assign me the mission.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 13)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_arcanum', NULL, 'npc_arcanum_class_trainer', 'greet', '[{"id": "greet", "text": "Knowledge is power, but power must be wielded correctly. What arcane discipline do you wish to master?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Is there a trial I can undertake?", "next": "take_quest"}, {"text": "Tell me about Arcanum combat.", "next": "lore"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We Seekers unravel the mysteries of the Prima Materia. Our combat relies on unlocking the universe''s hidden truths and bending them to our will.", "options": [{"text": "Fascinating.", "next": "greet"}, {"text": "I must go.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Peer into the void and choose your path. The arcane arts demand absolute dedication — once chosen, your path is sealed by the Prima Materia itself.", "options": [{"text": "Let me study the available paths.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let us refine your mastery over the arcane.", "options": []}, {"id": "take_quest", "text": "Advancement among the Seekers is not given — it is discovered. There is an anomaly in the field that requires investigation. Collect samples, neutralize any corrupted entities you encounter, and document your findings. Your performance will determine whether you are worthy of deeper knowledge.", "options": [{"text": "I need more time to prepare.", "next": "greet"}, {"text": "I accept the trial.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 14)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_hegemony', NULL, 'npc_hegemony_class_trainer', 'greet', '[{"id": "greet", "text": "Only the strong survive the scrap yards! Are you here to forge yourself into a weapon?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Give me a fight to prove myself.", "next": "take_quest"}, {"text": "Tell me about Hegemony tactics.", "next": "lore"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We don''t rely on shiny tech or fancy magic. Pure, unadulterated physical superiority and raw firepower rule the Iron Hegemony.", "options": [{"text": "Understood, Marshal.", "next": "greet"}, {"text": "I have to leave.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Pick your weapon, pick your war. Once you commit, there''s no going soft. The Hegemony doesn''t tolerate indecision.", "options": [{"text": "Show me what I can become.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let''s beat some combat sense into you.", "options": []}, {"id": "take_quest", "text": "You want a new class? Then earn it with blood and sweat. There''s a pack of hostiles causing trouble in our territory. Go out there, crush every last one of them, and drag yourself back here alive. Do that, and I''ll consider you worthy of advancement.", "options": [{"text": "Not yet, Marshal.", "next": "greet"}, {"text": "Point me to the fight.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 15)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_custodians', NULL, 'npc_custodian_class_trainer', 'greet', '[{"id": "greet", "text": "The Custodians protect the balance of Xylos. How may I assist your training?", "options": [{"text": "Change my class specialization.", "next": "class", "action": "open_class_change"}, {"text": "Improve my combat techniques.", "next": "skills", "action": "open_skill_training"}, {"text": "I wish to undertake an advancement trial.", "next": "take_quest"}, {"text": "Tell me about the Custodians.", "next": "lore"}, {"text": "I''ll return later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Galactic Custodians exist to preserve order across Xylos and prevent total war between factions.", "options": [{"text": "I understand.", "next": "greet"}, {"text": "Thank you.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Your specialization will define your role in maintaining the balance. Choose wisely — this decision is permanent and irreversible.", "options": [{"text": "Show me the available roles.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Focus. Precision leads to victory.", "options": []}, {"id": "take_quest", "text": "The Custodians require balanced judgment, not just raw power. We have received reports of instability in a nearby zone. Investigate the disturbance, neutralize any threats to civilian safety, and file a complete report. Your conduct during this mission will determine your eligibility for specialization advancement.", "options": [{"text": "I will return when I am prepared.", "next": "greet"}, {"text": "I accept the assignment.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 16)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_mercenary', NULL, 'npc_mercenary_class_trainer', 'greet', '[{"id": "greet", "text": "Heh. Another rookie looking to survive out here?", "options": [{"text": "Change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train some combat skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Got any jobs that''ll get me promoted?", "next": "take_quest"}, {"text": "Any advice for surviving Xylos?", "next": "lore"}, {"text": "I''m good.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Rule one kid — never trust a quiet battlefield. Rule two — always keep your weapon ready.", "options": [{"text": "Good advice.", "next": "greet"}, {"text": "I''ll remember that.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Listen up, kid. You pick a fighting style and you stick with it. No refunds, no do-overs. That''s how it works out here.", "options": [{"text": "Alright, show me what''s on the table.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Alright, let''s sharpen those skills.", "options": []}, {"id": "take_quest", "text": "Heh, eager one. Alright, I''ve got a contract that nobody else wants to touch — too dangerous, too dirty. Clear out the target zone, grab whatever intel you can find, and make it back in one piece. Pull that off and I''ll bump you up. Fail, and... well, don''t fail.", "options": [{"text": "Let me think about it.", "next": "greet"}, {"text": "Hand me the contract.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 17)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_meridian', NULL, 'npc_meridian_class_trainer', 'greet', '[{"id": "greet", "text": "Time is credits, friend. You looking to learn how to fight dirty and get paid, or what?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Any high-paying jobs that come with a promotion?", "next": "take_quest"}, {"text": "Tell me about Cartel combat.", "next": "lore"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Fair fights are for fools who end up dead and broke. We hit fast, hit where it hurts, and make sure we walk away with the prize.", "options": [{"text": "Makes sense.", "next": "greet"}, {"text": "I''m out.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "Every specialist has a niche. Pick yours and own it — the Cartel doesn''t pay for second chances. Choose once, profit forever.", "options": [{"text": "Let me see the specializations.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let''s sharpen those tricks up.", "options": []}, {"id": "take_quest", "text": "Advancement in the Cartel means proving you can deliver results. There''s a shipment route that''s been compromised — hostiles are raiding our supply lines. Eliminate the threat, secure the cargo, and bring back proof. Do this cleanly and your specialization upgrade is guaranteed. Mess it up and you owe me for the lost merchandise.", "options": [{"text": "I''ll pass for now.", "next": "greet"}, {"text": "Consider it done.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 18)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_omnicorp', NULL, 'npc_omnicorp_class_trainer', 'greet', '[{"id": "greet", "text": "Welcome to OmniCorp Combat Systems. Would you like to optimize your combat designation today?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Are there field tests available for advancement?", "next": "take_quest"}, {"text": "Tell me about OmniCorp warfare.", "next": "lore"}, {"text": "No, thank you.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Efficiency above all. Through cybernetic enhancements and predictive AI targeting, our operatives achieve a 98.7% success rate.", "options": [{"text": "Impressive stats.", "next": "greet"}, {"text": "Terminating conversation.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "WARNING: Combat system reconfiguration is a one-time procedure. Once installed, your combat protocol cannot be reverted. Proceed with caution.", "options": [{"text": "Display available combat systems.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Initiating skill calibration protocol...", "options": []}, {"id": "take_quest", "text": "NOTICE: Class advancement requires completion of a certified field evaluation. Proceed to the designated combat zone, eliminate all marked targets within operational parameters, and return sensor data for analysis. Performance metrics will be reviewed by OmniCorp Tactical Division. Minimum efficiency threshold: 85%.", "options": [{"text": "Postpone evaluation.", "next": "greet"}, {"text": "Initiate field test.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 19)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_shard', NULL, 'npc_shard_class_trainer', 'greet', '[{"id": "greet", "text": "The Aethel whispers, child. Are you ready to embrace its holy light and purge the non-believers?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "How can I prove my devotion for advancement?", "next": "take_quest"}, {"text": "Tell me about Shard doctrine.", "next": "lore"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Technology is a cancer. We draw our strength directly from the divine fragments of the Aethel Shard, striking with zealous fury.", "options": [{"text": "I see the truth.", "next": "greet"}, {"text": "I must pray.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "The Aethel reveals your true calling, child. But once chosen, your soul is bound to that path. The Shard does not grant second chances.", "options": [{"text": "Show me the sacred paths.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let the light empower your strikes.", "options": []}, {"id": "take_quest", "text": "The Aethel tests all who seek its deeper gifts. A corruption festers in the wilds — an affront to the Shard''s sacred energy. Purge the tainted creatures, cleanse the desecrated ground, and offer the remains to the Shard. Return purified, and the Aethel will open a new path for your soul.", "options": [{"text": "I must meditate on this.", "next": "greet"}, {"text": "I will carry out the purification.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 20)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_trainer_legion', NULL, 'npc_legion_class_trainer', 'greet', '[{"id": "greet", "text": "Honor and blood, warrior! Do you seek to prove your worth to the Starforged Legion?", "options": [{"text": "I want to change my class.", "next": "class", "action": "open_class_change"}, {"text": "Train my skills.", "next": "skills", "action": "open_skill_training"}, {"text": "Is there a trial of honor I can undertake?", "next": "take_quest"}, {"text": "Tell me about Legion combat.", "next": "lore"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "A home is earned by strength of arms. We fight with disciplined formations, unbreakable shields, and the memory of our lost world.", "options": [{"text": "For the Legion.", "next": "greet"}, {"text": "Farewell.", "next": "exit", "action": "exit"}]}, {"id": "class", "text": "A warrior chooses their blade once and carries it to the grave. No excuses, no regrets. Declare your role, soldier — this is permanent.", "options": [{"text": "Show me the battlefield roles.", "next": "greet", "action": "open_class_change"}]}, {"id": "skills", "text": "Let us hone your combat prowess.", "options": []}, {"id": "take_quest", "text": "Every rank in the Legion is forged in battle. There is a warzone that needs a soldier with guts. March into hostile territory, hold the line against incoming waves, and eliminate the commanding officer. Return with their insignia as proof. Do this with honor, and your advancement is earned — not given.", "options": [{"text": "I need to gear up first.", "next": "greet"}, {"text": "For the Legion. I march now.", "next": "exit", "action": "take_quest"}]}]'::jsonb, 'dialog_tree_master.json', 21)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_master', NULL, 'npc_class_architect', 'greet', '[{"id": "greet", "text": "Every warrior begins somewhere. I can guide you to your true path.", "options": [{"text": "Change my class.", "next": "class_menu", "action": "open_class_change"}, {"text": "Tell me about classes.", "next": "explain"}, {"text": "Not now.", "next": "exit", "action": "exit"}]}, {"id": "explain", "text": "Each class represents a different combat philosophy. Choose wisely, for it will shape your journey across Xylos.", "options": [{"text": "Let me choose.", "next": "class_menu", "action": "open_class_change"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "class_menu", "text": "Focus your will. Your path awaits.", "options": []}]'::jsonb, 'dialog_tree_master.json', 22)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_class_advisor', NULL, 'npc_class_advisor', 'intro', '[{"id": "intro", "text": "Welcome to Xylos, traveler. Before you begin your journey, you must choose a combat class.", "options": [{"text": "Where can I choose a class?", "next": "locations"}, {"text": "Tell me what a class is.", "next": "explain"}, {"text": "I''ll explore on my own.", "next": "exit", "action": "exit"}]}, {"id": "explain", "text": "A class defines how you fight and the abilities you will learn. Trainers across the capitals of Xylos can guide you in choosing your path.", "options": [{"text": "Where can I find these trainers?", "next": "locations"}, {"text": "Understood.", "next": "exit", "action": "exit"}]}, {"id": "locations", "text": "Class Trainers can be found in the major capitals of Xylos. Visit one of them to begin your training.", "options": [{"text": "Thanks for the guidance.", "next": "exit", "action": "exit"}]}]'::jsonb, 'dialog_tree_master.json', 23)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_concordium_ama_main', NULL, 'NPC_CONCORDIUM_EXCHANGE', 'greet', '[{"id": "greet", "text": "AMA Branch Office — Concordium. I can facilitate exchanges between your faction currency (AMC) and the universal Credent (CRD). Current rates fluctuate based on twelve economic factors. State your intent.", "options": [{"text": "I want to exchange currency.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "How do exchange rates work?", "next": "explain_rates"}, {"text": "Nothing for now.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "Exchange rates are computed dynamically by the AMA. Factors include territory control, treasury health, inflation, trade volume, and more. A sliding fee of 1–5% applies per transaction based on volume. The rate is always live — it reflects the current state of the economy.", "options": [{"text": "I want to exchange now.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "I''ll come back later.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Processing your exchange request. The AMA Ledger records all transactions.", "options": []}]'::jsonb, 'dialog_tree_master.json', 24)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_arcanum_ama_main', NULL, 'NPC_ARCANUM_EXCHANGE', 'greet', '[{"id": "greet", "text": "Fascinating to have a client! I handle QNT-to-CRD and CRD-to-QNT exchanges here. The volatility of Arcanum currency is actually a mathematical marvel — it responds to knowledge sector output and energy research cycles. But I digress. How can I assist?", "options": [{"text": "I want to exchange currency.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Tell me more about the rates.", "next": "explain_rates"}, {"text": "I''ll think about it.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "QNT value is heavily influenced by Arcanum''s research output and territorial control. When the Seekers control high-value knowledge sites, QNT strengthens considerably. Fee is 1–5% sliding scale by volume. I''ve written four papers on this if you''d like—", "options": [{"text": "Just the exchange, please.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Maybe later.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Splendid! Initiating exchange protocol. The AMA Ledger awaits your input.", "options": []}]'::jsonb, 'dialog_tree_master.json', 25)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_iron_ama_main', NULL, 'NPC_IRON_EXCHANGE', 'greet', '[{"id": "greet", "text": "TERMINAL IH-3 ACTIVE. SERVICES: IGT-CRD EXCHANGE. CURRENT RATE: LIVE. FEE: 1-5%. SELECT OPTION.", "options": [{"text": "Begin exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Display rate information.", "next": "explain_rates"}, {"text": "Abort.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "IGT RATE FACTORS: MILITARY OUTPUT, INDUSTRIAL PRODUCTION, TERRITORY, TREASURY HEALTH, TWELVE VARIABLES TOTAL. RATE RANGE: 0.25-3.00 CRD PER IGT. FEE DEDUCTED FROM OUTPUT. NO FURTHER INFORMATION AVAILABLE.", "options": [{"text": "Begin exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Abort.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "TRANSACTION INITIATED. AWAITING INPUT.", "options": []}]'::jsonb, 'dialog_tree_master.json', 26)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_meridian_ama_main', NULL, 'NPC_MERIDIAN_EXCHANGE', 'greet', '[{"id": "greet", "text": "Welcome to the busiest AMA desk in Xylos! We handle AUC-to-CRD and back with the smoothest process you''ll find anywhere. Between us — when trade volume is high here, you might find the rates particularly favourable. Shall we?", "options": [{"text": "Let''s exchange currency.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Tell me about the rates.", "next": "explain_rates"}, {"text": "Not right now.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "AUC is tied to trade dominance. The Cartel''s grip on commerce directly strengthens the Aurum Cipher. High-volume transactions attract a lower fee — 1% for large trades, 5% for small ones. My advice? Don''t exchange in small increments.", "options": [{"text": "Good tip. Let''s exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "I''ll keep that in mind.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Excellent choice. Opening the exchange interface now.", "options": []}]'::jsonb, 'dialog_tree_master.json', 27)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_omnicorp_ama_main', NULL, 'NPC_OMNICORP_EXCHANGE', 'greet', '[{"id": "greet", "text": "OmniCorp AMA Integration Node online. Services available: OMC-to-CRD exchange, CRD-to-OMC exchange. OmniCorp is not responsible for rate fluctuations. The AMA guarantees ledger integrity. Terms and conditions apply. How may I process your transaction?", "options": [{"text": "Open exchange interface.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Rate information.", "next": "explain_rates"}, {"text": "Disconnect.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "OmniCred value is indexed to OmniCorp''s patent portfolio valuation, off-world trade agreements, R&D throughput, and resource export volumes. Rate range: 0.25 to 3.00 CRD per OMC. Fee: 1% to 5% sliding by volume. Processing time: immediate. Disclaimer: past rate performance is not indicative of future results.", "options": [{"text": "Proceed with exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "End session.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Initiating exchange module. CoreNet™ connection secure.", "options": []}]'::jsonb, 'dialog_tree_master.json', 28)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_shard_ama_main', NULL, 'NPC_SHARD_EXCHANGE', 'greet', '[{"id": "greet", "text": "...The Shard breathes. And in its breath, all things flow — including currency. I am Mirya. I can exchange your Aethel-Tithes (ATH) for Credent, or the reverse. The AMA requires I do this. The Shard permits it. What do you seek?", "options": [{"text": "I seek currency exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Tell me about the exchange.", "next": "explain_rates"}, {"text": "I will return another time.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "ATH is sacred in nature, and thus unpredictable by worldly measures. Its value rises when the Shard controls the pulse-points of Xylos, and falls when the sacred sites are held by those without faith. The AMA has learned to accept this. A fee is taken — 1 to 5 of every 100 — as offering to the system.", "options": [{"text": "I am ready to exchange.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "I will meditate on it.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "May the exchange be balanced. The interface opens before you.", "options": []}]'::jsonb, 'dialog_tree_master.json', 29)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dlg_legion_ama_main', NULL, 'NPC_LEGION_EXCHANGE', 'greet', '[{"id": "greet", "text": "Rex Valdur, AMA Forward Station. We handle Legion Scrip (LSC) and CRD, both directions. I run a tight operation here — fast processing, fair rates, no nonsense. The Legion appreciates efficiency. So do I. What are we moving?", "options": [{"text": "Exchange currency.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "What are the current rates?", "next": "explain_rates"}, {"text": "Stand down for now.", "next": "exit", "action": "exit"}]}, {"id": "explain_rates", "text": "LSC tracks Legion military readiness and territorial control. Strong Legion presence in contested zones pushes the Scrip up. Fee is 1–5% depending on volume — high-volume traders get the better deal. I''ve seen this station process 50,000 LSC in a single session. Don''t be shy.", "options": [{"text": "Let''s go.", "next": "confirm_exchange", "action": "currency_exchange"}, {"text": "Not today.", "next": "exit", "action": "exit"}]}, {"id": "confirm_exchange", "text": "Exchange interface open. Make it count.", "options": []}]'::jsonb, 'dialog_tree_master.json', 30)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_001', 'fq_conc_001', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "You there. I''m Commander Lirien Vale, and I''ve been waiting for someone with actual field potential to walk through that gate. The Aethel Gardens used to be the crown jewel of Xylos — terraced groves fed by the Cradle''s overflow, bioluminescent at night, one of the few things that survived the Severance mostly intact. Now they''re choking with Forest Slimes, and every convoy we lose to the ooze is another crack in Concordium''s supply chain.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Slimes aren''t random, Operative. Before the Severance, this soil was saturated with clean aethel energy from the Cradle''s natural overflow. When the Siphon overloaded and the Shard shattered, that overflow became contaminated — every root, every organism that absorbed it twisted into something new. The Slimes are what the Gardens'' old microbiome became after three hundred years of Severance corruption. The Great Schism cost me half my garrison to Iron Hegemony defectors, so I''m running this outpost lean. These supply routes are the only uncontested corridor into Nexus Core. They fall, the whole Concordium operation gets squeezed.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Every route you clear is a vein we restore to the Cradle. Defeat five Forest Slimes and bring me a gel sample — the research division wants the contamination profile. For Nexus. Move out, Operative.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 31)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_002', 'fq_conc_002', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The corridor is clearer, but the outpost perimeter is now surrounded on three sides by Aethel Sproutlings — corrupted seedlings that haven''t seen clean sunlight since before the Schism. They''ve been pressing in from the northern grove since dawn, and two of my guards reported cuts through standard-issue armor plating. The perimeter must hold.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "This outpost was built to serve as the Gardens'' forward monitoring station — we track aethel output fluctuations and relay them to Nexus Core for calibration. If these Sproutlings breach the perimeter and reach the monitoring equipment, we lose visibility on the entire eastern corridor. After the Schism, when the Iron Hegemony faction broke away and took a third of our engineering staff, we lost the ability to run redundant systems. There is no backup monitoring station. This one is it.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Four Sproutlings on the perimeter line, one minor essence sample for biological documentation. The Concordium does not cede ground it has already paid for. Hold the line.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 32)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_003', 'fq_conc_003', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "We have a structural problem. The bio-conductive wiring running through the Gardens'' eastern grove — fifteen years of installation work, the same wiring that channels aethel energy from the Gardens into Nexus Core — is being eaten alive. Garden Mites have bored into the conduit walls and they''re feeding on the wiring''s energy conduction layer. If the eastern grove fails, we lose primary power routing to three Nexus sectors.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The bio-conductive wiring was an innovation of the Concordium''s founding engineers — the same generation who first successfully reactivated the Siphon after the Severance. It took fifteen years because the original Aethelgardian conduit infrastructure had been shattered along with everything else. These Mites evolved specifically to consume that wiring — which means they''ve been a problem since the conduits were first laid. We''ve been managing the infestation for years. This incursion is worse. I cannot write the report that explains we lost Nexus Core power because of insects.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Six Garden Mites in the eastern grove, three chitin samples for the engineering division — they want to analyze what the Mites are extracting from the wiring. Everything is data, Operative. Everything.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 33)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_004', 'fq_conc_004', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The aethel conduits in the eastern corridor are humming at the wrong frequency — lower, dragging, like something has changed their internal structure. Our engineering team found the cause: Feral Rootlings have grown through the conduit walls and they''re drinking raw aethel energy directly from the lines. They weren''t in any pre-Severance bestiary. They''re something the conduits themselves created.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The conduits were carved by the Concordium''s founders — people who rebuilt the Aethel Cradle from ruins and wept when it first activated. They ran the conduit lines through the Gardens'' root systems to take advantage of the organic conductivity. The Rootlings were probably ordinary plant life before they contacted raw aethel. Three hundred years of feeding on the conduit''s energy has warped them into something that exists only in this place, dependent on the infrastructure they''re destroying. If the conduit lines fail tonight, Nexus Core goes dark. The Arcanum will be on the doorstep before morning.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Six Feral Rootlings from the conduit sections — cut them out. Four living root samples for the engineering division''s biological database. The Concordium does not discard knowledge. Not even from the things trying to kill us.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 34)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_005', 'fq_conc_005', 'npc_concordium_class_trainer', 'greeting', '[{"id": "greeting", "text": "Commander Vale''s field reports reached Nexus Core faster than you''d expect. I''m Instructor Kael — the Concordium''s master trainer, a veteran of the earliest post-Schism skirmishes when the Hegemony''s defection was still raw and every patrol felt like it could become a civil war. Vale says you have field potential worth shaping. The Concordium rebuilt the Aethel Cradle from ruins. It did not do that with generalists. Before you go further, you need to choose your path.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Concordium recognizes three combat philosophies forged in the crucible of post-Schism survival. The Shield holds the line and absorbs damage so others don''t have to — the Schism taught us that fortified ground is the difference between survival and collapse. The Blade moves fast and strikes before the enemy can adapt — because the Hegemony''s defection proved that waiting too long costs everything. The Conduit channels aethel energy as force, reading the battlefield and amplifying the team — because the Cradle''s power is not just for industry. Every Concordium operative makes this choice. The wrong answer will not be punished. But it will define every engagement you fight from this day forward.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Speak with me at the training station, review your class selection, then put your calibration to the test against three Forest Slimes in the field. The Concordium''s future is built on individuals who chose wisely. Choose well, Operative.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 35)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_006', 'fq_conc_006', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "Welcome to the Broken Civil Quarter — what''s left of it. Before the Great Schism, this was the beating heart of unified Nexus, where the Concordium''s administrative and engineering divisions worked side by side in buildings that actually had intact roofs. The Schism tore this district apart as badly as it tore the faction apart. Concordium engineers have located a viable breach point into the main reclamation corridor. But Tunnel Crawlers have nested in it.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Civil Quarter''s architecture is layered history. The upper buildings were built post-Severance by the original unified Concordium — the same faction that rebuilt the Cradle. The lower infrastructure, the tunnel system, dates back to before the Severance, possibly Aethelgardian construction. Tunnel Crawlers evolved in those lower tunnels, isolated from whatever happened above for centuries. They''re not aggressive by nature — they''re territorial, which means the breach point we''ve identified is directly through their primary nesting territory. There is no alternative route. We stake the Concordium''s flag in this district, or we cede it to whatever faction moves faster.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Six Tunnel Crawlers from the main breach, one chitin sample for materials documentation. Every street we reclaim in this district is a reminder that unity was once possible here. Clear it. For the Cradle.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 36)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_007', 'fq_conc_007', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "We have a retrieval problem. The original unified Concordium buried supply caches throughout the Civil Quarter — medical supplies, engineering manuals, communication arrays — against the day the Schism might be reversed and the faction reunified. Scavengers have been looting them for years. Some of those engineering manuals were written by my mother.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The caches were designed to survive indefinitely, sealed against contamination, indexed against the original Concordium''s administrative database — a database that the Schism split into three fragments, each faction holding a piece. The Scavengers aren''t ideologically motivated; they sell to whoever pays. That means Hegemony buyers, Arcanum buyers, possibly even the Meridian Compact. Every manual they extract from those caches and sell to a rival faction is knowledge that was meant to rebuild Nexus, going instead to fragment it further. The scrap metal they collect is secondary. The information is what matters.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Five Scavengers eliminated from the reclaimed sector, two rusted scrap units recovered for materials analysis. The Concordium remembers what was buried here. We''re taking it back.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 37)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_008', 'fq_conc_008', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "I know it sounds absurd — the Concordium survived the Severance, the Schism, three rival factions, and now a rat threatens the advance. A Civil Rat Alpha has claimed the old archive building and bred a colony large enough to collapse the reclaimed sector''s food supply if the infestation spreads. The irony is not lost on me. But the archive building contains something more important than the rat''s pride.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "That building was a secondary administrative repository for the original unified Concordium — not the primary archive, but a significant one. Communications logs from the weeks before the Schism, engineering specifications for Cradle infrastructure that none of the three post-Schism factions have successfully reconstructed, personnel records from the founding generation. The Alpha has nested in the lower storage vaults. Its colony has been using the document storage containers as nesting material. Every week we wait, more of what''s inside becomes irretrievably compromised. The Concordium does not accept that outcome.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Hunt the Alpha in the archive building, clear three Civil Scavengers from the surrounding area. Document the nesting site for our damage assessment team. Everything is data, even the cost of our failures.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 38)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_009', 'fq_conc_009', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "Deep in the ruins, there is a Rusted Warden still patrolling. Automated guardian technology from before the Schism — programmed with the original unified Concordium''s authentication protocols. It doesn''t recognize our current insignia. It doesn''t recognize any of the Schism''s successor factions. It doesn''t recognize anything except the threat-assessment protocols written into it over a century ago. And we are, by its reckoning, unauthorized personnel.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Our engineering team tried to reprogram it. Twice. The first team was driven back before they could interface with the command core — the Warden''s automated response treated the reprogramming attempt as a hostile intrusion. The second team managed to reach the interface before a power surge fried their equipment. The Warden''s command protocols are hardwired to the original unified Concordium''s authentication system — a system that no longer exists. The people who wrote those protocols are dead. The faction that issued those credentials fragmented into three. The machine doesn''t know any of this. It just knows its orders haven''t changed.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Two Rusted Wardens in the deep ruins, four Feral Scavengers cleared from the perimeter. Collect the circuit components from the Wardens for our engineering archives. The Concordium built these machines. Understanding how they failed is part of understanding what we lost.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 39)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_010', 'fq_conc_010', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "There is a Slime King in the sewers beneath the Civil Quarter. The sewers that the Concordium''s founding engineers designed as emergency water routing for a city of four million people — the infrastructure that was supposed to guarantee Nexus''s survival through any crisis. It has been the throne room of a Slime King for approximately eighty years. Since shortly after the Schism, if the biological dating on the core samples is accurate.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Slime King is not the product of the Severance''s initial corruption. It grew here, in the dark, after the Schism fractured the faction that built this place. The founding engineers'' greatest infrastructure achievement became an abandoned space within a generation of its construction. The Severance''s contamination seeped into the neglected water system, and something coalesced in the absence of maintenance, of oversight, of care. This is what neglect looks like, given eighty years and a corrupted water supply. The Concordium''s failure to hold this district together created the conditions for this creature''s existence.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "The Slime King in the underground cistern, two mutant hound escorts cleared. Collect the slime core — our research division wants the biological profile. End its reign, Operative. The Concordium reclaims what it built.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 40)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_011', 'fq_conc_011', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "You''ve earned the right to see it. The Aethel Cradle''s Outer Ring — the great machine the Concordium built around Xylos''s most powerful energy source. The original engineers wept when they first activated it. I wasn''t there, but I''ve read the field journals, and I believe that account completely. Now the Outer Ring is contested ground, and every faction wants what it contains. I need you to scout it and make sure the Concordium holds the advantage.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Outer Ring was the Concordium''s greatest engineering achievement after the Cradle reactivation itself — a network of energy capture platforms encircling the Siphon''s primary output zone. Before the Great Schism, it supplied Nexus Core with enough aethel-derived power to run every system in the city indefinitely. The Schism disrupted the maintenance rotation, and now three factions fight over control of platforms that none of us has the full engineering staff to run properly. The void fragments you''ll find in the flux rift sites are debris from reality-thin zones where the Cradle''s energy output causes spatial instability. We use them as calibration data. They tell us how close to the edge the Outer Ring is operating.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to the Outer Ring, collect three void fragments from the flux rift sites. Every data point we gather is another argument for why the Concordium — not the Hegemony, not the Arcanum — should control the Cradle. For Nexus.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 41)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_012', 'fq_conc_012', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Cradle Anomaly Wolves have been sighted near the flux rifts in the Outer Ring''s western sector. These aren''t standard predators — they''re what happens when a species spends generations in proximity to a malfunctioning aethel source. Their howls are operating on the same frequency band as our harmonic resonators. Every time a pack vocalizes near the resonators, the calibration drifts. Unchecked drift leads to cascade failure. The Concordium nearly lost the Cradle once. I refuse to let it happen again.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The resonators are what maintain stable energy output from the Outer Ring — they''re the mechanism that prevents the Cradle''s power from spiking into an uncontrolled surge the way it did during the Great Severance. The Aethelgardians didn''t have resonator technology when they activated the Siphon. That''s why the Shard shattered. We rebuilt the Siphon and added the resonator network specifically because we understood what went wrong. If the Anomaly Wolves'' vocalizations interfere with that network and cause a calibration failure, we recreate the conditions of the Severance. The entire Outer Ring''s operation is at risk from creatures that are themselves a product of the Severance''s original damage.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Five Anomaly Wolves from the western flux rift zones, three wild hide samples for biological documentation. The Concordium''s promise is that this never happens again. Help us keep it.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 42)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_013', 'fq_conc_013', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Cradle Anomaly Beastlings have nested in the maintenance shafts of the Outer Ring''s stabilizer array. Smaller than the Wolves, faster, and they''ve compromised the physical access routes our engineering teams use to maintain the stabilizers. Two maintenance rotations have been turned back already. If the array goes offline, the Arcanum Seekers will be on our doorstep before the stabilizers finish cooling.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The stabilizer array is what prevents the Outer Ring''s energy output from becoming unstable during peak load cycles. Think of it as the Cradle''s immune system — it detects imbalances and corrects them automatically, without human intervention. The Beastlings are probably the same species as the Anomaly Wolves at a juvenile life stage — the biological team isn''t certain, but their behavioral patterns suggest it. What they share is origin: creatures shaped by sustained aethel radiation, adapted to environments that should be lethal. They''re thriving in the maintenance shafts because the background radiation there would kill a standard organism in hours. It''s not killing them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Six Beastlings from the maintenance shafts, four void fragments from the rift sites they''re drawn to. Our engineering teams are waiting to resume maintenance rotations. Clear the way.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 43)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_014', 'fq_conc_014', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Cradle Fragment Beasts are carrying unstable aethel cores inside their bodies — literal shards of the original Aethel Shard, still radiating energy, embedded in living hosts. The Arcanum Seekers want them captured for study. The Children of the Shard want them worshipped. The Concordium wants them contained before they detonate near the Outer Ring''s flux regulators and cause a cascade failure.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The prevailing theory from our biology division: in the immediate aftermath of the Severance, when the Shard shattered, the fragment scatter pattern spread across several hundred kilometers. Small organisms in the high-contamination zones ingested fragment material before the biological hazard was understood. Three centuries of biological integration have fused the fragment material with the host organism''s metabolic system. The cores are still energetically active — that''s why the Beasts are dangerous, and why they''re drawn to the Outer Ring. The Cradle''s energy output resonates with the embedded fragments. We believe they''re trying to return the shards to the source. They cannot be allowed to do that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Five Fragment Beasts from the northern sector, three aethel fragment cores recovered before detonation threshold. Ideology is secondary to operational integrity, Operative. Contain the threat.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 44)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_015', 'fq_conc_015', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "Sector Seven has been silent for three hours. The Resonance Bats swarming the communication arrays on the Outer Ring''s southern platform have effectively jammed our entire coordination network for that sector. These creatures evolved using the Cradle''s own harmonic emissions as echolocation — when they pulse near the arrays, their biological signal is indistinguishable from system noise. I check the comms every thirty seconds. Nothing comes back.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The communication arrays are how the Concordium coordinates Outer Ring defense. Without them, every patrol sector operates independently, without intelligence sharing, without support coordination. Three hours of silence means three hours where a Hegemony incursion, an Arcanum infiltration, or a void breach could happen in Sector Seven and we wouldn''t know until a patrol stumbled into it. The Resonance Bats are not strategically motivated — they''re drawn to the array''s harmonic output because it matches their echolocation frequency. But the effect is operationally equivalent to deliberate jamming. The Resonance Golems guarding their nest are amplifying the interference. Both have to go.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Eight Resonance Bats from the array perimeter, two Resonance Golems from the nest site. Restore contact with Sector Seven. The Concordium does not go dark.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 45)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_016', 'fq_conc_016', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "Three scouts went dark in the eastern sector three days ago. I''ve entered their names in the operational record. Now I need you to enter the sector and recover the data they were carrying — void fragment calibration samples and an intelligence packet on Hegemony troop movements near the Cradle''s loading docks. The data doesn''t expire. The scouts are gone. The mission continues.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The void fragment calibration samples they carried are irreplaceable in the short term — we pulled them from a specific flux rift that has since destabilized and is no longer safely accessible. The intelligence packet was compiled over six weeks by a surveillance team I cannot replace either. The Cradle Anomaly Wolves are responsible for the scouts'' situation — we found trace evidence consistent with pack behavior in the vicinity of their last reported position. I report this precisely, without additional comment, because that is what the operational record requires of me. And because the mission requires clarity, not grief.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Collect three void fragment samples from the scout site coordinates, defeat four Anomaly Wolves in the area. Bring back what they carried. The Concordium remembers its own.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 46)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_017', 'fq_conc_017', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "A void breach has opened in the Outer Ring''s north platform. Not a flux rift — a full breach, where the boundary between normal space and whatever geometry feeds the void has thinned to near-zero. Fragment Beasts are pouring through and growing stronger with each surge. Concordium engineers believe the breach appeared the same week the Iron Hegemony began unauthorized excavation near the Cradle''s base. That may be coincidence. It may not.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Hegemony''s excavation team has been drilling into the Cradle''s outer geological substrate — the deep rock layer where the original Aethelgardian construction anchored the Siphon''s foundation. If they''ve penetrated the Siphon''s root structure, they may have destabilized the same containment geometry that the Aethelgardians built to prevent void ingress. This is the mechanism the Concordium believes triggered the original Severance — not the Siphon overload itself, but a void geometry failure that the overload then exploited. The Hegemony either doesn''t know what they''ve done, or they don''t care. Neither possibility is acceptable.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Six Fragment Beasts near the breach site, two aethel fragments recovered before detonation. The breach will close naturally once the Fragment density drops below threshold. Move quickly, Operative.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 47)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_018', 'fq_conc_018', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Resonance Golems in the deep Outer Ring have established a concentration point — not a random nest, a deliberate defensive arrangement. Concordium historians believe these constructs are the Aethel Cradle''s original defense systems, built by the same Aethelgardian architects who first activated the Siphon. They''re still following protocols from before recorded history. And their harmonic pulses are rewriting our communication protocols with something older and stranger.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Golem emissions are what our signal analysis team is describing as ''pre-language'' — structured harmonic patterns that predate anything in the Concordium''s linguistic database. The same patterns appear in fragments of Aethelgardian inscription recovered from the Cradle''s deeper chambers, but no one has been able to fully translate them. The Golems are broadcasting these patterns continuously, and our communication infrastructure is beginning to incorporate them into its error-correction responses. In six weeks, if this continues, our comm arrays will be outputting Aethelgardian protocols instead of Concordium standard. The Concordium does not discard knowledge, but neither does it allow unknown protocols to overwrite operational infrastructure.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Three Resonance Golems in the deep chambers, six Resonance Bats cleared from the surrounding area. Document the Golem emissions before you engage — every recording is data the Concordium will eventually understand.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 48)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_019', 'fq_conc_019', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Resonance Echo has materialized. This is beyond the Bats and the Golems — this is a concentrated echo of the Cradle''s original harmonic signature, coalesced into something that our instruments cannot categorize. The Arcanum Seekers would call it a miracle. The Children of the Shard would call it a god-fragment. I call it a threat to Concordium communication infrastructure that is currently rewriting Sector Nine''s relay protocols in real time.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The best working theory from our research division: the Outer Ring''s deep electromagnetic structure stores harmonic data the way biological tissue stores memory — passively, impressionistically, over centuries. What we''re seeing is that stored data achieving coherent form, a self-organizing energy entity built from the Cradle''s accumulated operational history. It is, in the most literal sense, a memory of the Aethel Cradle itself — before the Schism, before the Severance, possibly before human contact with the Siphon. Whatever it''s trying to do, it is operating on a timeline and according to goals we cannot parse. The Concordium cannot allow unknown entities to operate autonomously within Cradle infrastructure.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "The Resonance Echo at the resonance chamber, four Fragment Beasts cleared from the surrounding area. Whatever it is — miracle, god-fragment, or accumulated data — it cannot rewrite the Cradle on its own terms. Not on my watch.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 49)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_020', 'fq_conc_020', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Outer Ring is not fully secured — it never will be, not while three factions and something older than all of them press against the Concordium''s borders. But we hold more of it today than we did a season ago, and that is because of what you''ve done here. This final sweep is also a test. The Concordium is evaluating you for Advanced assignment. The Cradle''s inner platforms await, and they will demand everything you have.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Inner Cradle Exclusion Zone, the Cradle Expanse, the contested zones where all factions have active operations — these are not the Gardens, Operative. The threats there are not Slimes and Sproutlings. They''re creatures that have adapted to direct Shard energy proximity, Aethelgardian defense constructs that have been operating for centuries without human oversight, void-adjacent entities that don''t have biological analogs in any known database. You will need every skill you''ve developed in the Gardens and the Civil Quarter and the Outer Ring. This final sweep will tell us if you''re ready.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Five Beastlings, five Resonance Bats, one void fragment. Final sweep of the Outer Ring''s remaining hostile concentrations. Show me you''re ready for what comes next, Operative.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 50)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_021', 'fq_conc_021', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Deep Incursion — Push deeper into the Inner Cradle Exclusion", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Travel to INNER_CRADLE_EXCLUSION; Collect 2x Materials\n\nComplete and report back.\n\nRewards: 600 EXP · 350 Currency · 350 Reputation · Con Nutrient Ration", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 51)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_022', 'fq_conc_022', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Inner Cradle Mutants exposed to raw aethel show extreme aggression", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 6x Inner Cradle Mutant; Collect 3x mutant_claw\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 650 EXP · 380 Currency · 380 Reputation · Mutagen Catalyst", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 52)
