values ('dialog_fq_conc_023', 'fq_conc_023', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Behemoth Rising — An Inner Cradle Behemoth has been spotted in the deep exclusion", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 1x Inner Cradle Behemoth; Defeat 4x Inner Cradle Mutant\n\nComplete and report back.\n\nRewards: 750 EXP · 420 Currency · 210 CRD · 450 Reputation · Titan Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 53)
