values ('dialog_fq_conc_024', 'fq_conc_024', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Sentinel Protocol — Cradle Sentinels guard the ancient Cradle gates", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 4x Cradle Sentinel; Collect 2x aethel_core_shard\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 700 EXP · 400 Currency · 400 Reputation · Damaged Servo Motor", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 54)
