values ('dialog_fq_conc_025', 'fq_conc_025', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. A Cradle Void Stalker has been hunting Concordium operatives in the Exclusion", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 2x Cradle Void Stalker; Collect 1x core_fragment\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 780 EXP · 440 Currency · 220 CRD · 470 Reputation · Void Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 55)
