insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_030', 'fq_conc_030', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. You have reached the Advanced threshold", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Speak with npc_concordium_class_trainer; Defeat 1x Resonance Echo; Defeat 1x Aethel Behemoth\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 2500 EXP · 1200 Currency · 800 Reputation · Con Elite Recovery Pack + Astral Phase Crystal Pure", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 60)
