values ('dialog_fq_conc_031', 'fq_conc_031', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. Concordium high command summons you to the Orbital Sentinel Command", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Travel to ORBITAL_SENTINEL_COMMAND; Collect materials\n\nComplete and report back.\n\nRewards: 900 EXP · 500 Currency · 500 Reputation · Con Elite Recovery Pack", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 61)
