values ('dialog_fq_conc_034', 'fq_conc_034', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Void Channeler — Aethel Void Channelers draw void energy into the Expanse", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 4x Aethel Void Channeler; Collect 2x Raw Aethel Fragment\n\nComplete and report back.\n\nRewards: 1400 EXP · 750 Currency · 375 CRD · 750 Reputation · Void Fragment", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 64)
