values ('dialog_fq_conc_050', 'fq_conc_050', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. The Ashen Drake rules the Shattered Heart", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Ashen Drake; Defeat 5x Drake Minion; Defeat 1x Gigantic Jotunn\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 8000 EXP · 4000 Currency · 2000 CRD · 2500 Reputation · Drake Heart + Ancient Scale", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 80)
