values ('dialog_fq_conc_052', 'fq_conc_052', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Void Dominance — With the Soul Fragmenter destroyed, Concordium initiates Operation Void Dom...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 8x Void Reaver; Defeat 5x Aethel Void Channeler\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 4500 EXP · 2200 Currency · 1100 CRD · 1500 Reputation · Void Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 82)
