values ('dialog_fq_conc_065', 'fq_conc_065', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Siphon Approach — The Aethel Siphon Core", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to AETHEL_SIPHON_CORE; Collect 2x thick_hide\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 5500 EXP · 2800 Currency · 1400 CRD · 1800 Reputation · Power Regulator Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 95)
