values ('dialog_fq_conc_066', 'fq_conc_066', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Hostile entities have infested the Siphon Core", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 8x Aethel Abyssal Reaver; Defeat 5x Aethel Void Channeler\n\nComplete and report back.\n\nRewards: 5800 EXP · 2900 Currency · 1450 CRD · 1900 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 96)
