values ('dialog_fq_conc_067', 'fq_conc_067', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Corrupted Behemoths are assaulting the Siphon Core''s primary conduits", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 3x Aethel Corrupted Behemoth; Collect 1x crystal_core\n\nComplete and report back.\n\nRewards: 6200 EXP · 3100 Currency · 1550 CRD · 2000 Reputation · Corrupted Synapse Cluster", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 97)
