values ('dialog_fq_conc_069', 'fq_conc_069', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. The seismic data is clear: the Gravity Titan stirs beneath the Cradle Expanse", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Collect 3x core_fragment; Defeat 1x Gigantic Jotunn\n\nComplete and report back.\n\nRewards: 7000 EXP · 3500 Currency · 1750 CRD · 2200 Reputation · Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 99)
