values ('dialog_fq_conc_070', 'fq_conc_070', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. MAXIMUM PRIORITY ALERT", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Gravity Titan; Defeat 5x Aethel Abyssal Reaver; Collect 1x void_channeler_core\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 20000 EXP · 10000 Currency · 5000 CRD · 7000 Reputation · Titan Core + Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 100)
