values ('dialog_fq_conc_071', 'fq_conc_071', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. The Gravity Titan''s defeat has revealed the entrance to the Prima Materia Forge", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Travel to PRIMA_MATERIA_FORGE; Collect 2x void_channeler_core\n\nComplete and report back.\n\nRewards: 6000 EXP · 3000 Currency · 1500 CRD · 2000 Reputation · Raw Aethel Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 101)
