values ('dialog_fq_conc_082', 'fq_conc_082', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. City Guardians — The Aethelgardian City is protected by ancient energy constructs", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 8x Aethel Rift Stalker; Defeat 1x Crystal Tyrant\n\nComplete and report back.\n\nRewards: 8500 EXP · 4200 Currency · 2100 CRD · 2700 Reputation · Quantum Distortion Stone", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 112)
