values ('dialog_fq_conc_083', 'fq_conc_083', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Precursor Secrets — The Precursor Archives reveal the existence of the World Engine", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Collect 4x abyssal_reaver_claw; Defeat 4x Aethel Abyssal Reaver\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 8800 EXP · 4400 Currency · 2200 CRD · 2800 Reputation · Cognitive Relay Node", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 113)
